use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const ROOT:&str="/tmp/zopro-grouping-lower-bound";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn median(mut xs:Vec<f64>)->f64{assert!(!xs.is_empty());xs.sort_by(f64::total_cmp);let n=xs.len();if n%2==1{xs[n/2]}else{(xs[n/2-1]+xs[n/2])/2.}}
fn gm(xs:&[f64])->f64{assert!(!xs.is_empty());(xs.iter().map(|x|{assert!(*x>0.);x.ln()}).sum::<f64>()/xs.len()as f64).exp()}
fn prepare(){let r=Path::new(ROOT);assert_eq!(read(r.join("native/result.json"))["status"],"complete");let artifact=read(r.join("native/on/artifacts.json"));let binary=artifact["binary"].as_str().unwrap();assert_eq!(hash(binary),artifact["binary_sha256"].as_str().unwrap());
 let mut config=read("/tmp/zopro-g2-owned-finish/perf-plan.json");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for a in [artifact.clone(),read("/tmp/zopro-grouping-module/native/candidate/artifacts.json")]{for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}add(a["binary"].as_str().unwrap(),&mut pins);}
 for(p,h)in config["pins"].as_object().unwrap(){if p.contains("/registry/")||p.starts_with("/tmp/zopro-keys/")||p.starts_with("/tmp/zopro-gnark-verify/"){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}}
 for rel in ["pipeline.rs","pipeline","native-plan.json","native/result.json","native/on/artifacts.json","native/on-core/stdout.log","native/on-prover/stdout.log"]{add(r.join(rel),&mut pins);}
 let old=read("/tmp/zopro-ready-c7a/remote-results/output/measure/config.json");let mut prior:BTreeSet<String>=serde_json::from_value(old["prior_proof_sha256"].clone()).unwrap();for f in ["/tmp/zopro-ready-c7a/proof-inventory.json","/tmp/zopro-stage-costs/proof-inventory.json"]{for(p,h)in read(f).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){prior.insert(h.as_str().unwrap().into());}}}assert_eq!(prior.len(),5238);
 let cases:Vec<_>=config["cases"].as_array().unwrap().iter().filter(|c|c["workers"]==32).cloned().map(|mut c|{c["rounds"]=json!(31);c["profile_rounds"]=json!(51);c}).collect();assert_eq!(cases.len(),9);
 let variants=json!([{"name":"accepted","binary":"/tmp/zopro-grouping-module/native/candidate-sdk"},{"name":"off","binary":binary,"environment":{"ZOPRO_CPU_GROUPING_LOWER_BOUND":"0"}},{"name":"on","binary":binary,"environment":{"ZOPRO_CPU_GROUPING_LOWER_BOUND":"1"}}]);
 let mut steps=Vec::new();for c in &cases {for p in [c["image"].as_str().unwrap(),c["request"].as_str().unwrap()]{add(p,&mut pins);}for mode in ["off","on"]{let name=format!("{}-{mode}",c["name"].as_str().unwrap());let proofroot=r.join("preflight-proofs").join(&name);let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();let d=proofroot.join(stem);let mut env=config["environment"].clone();env["RAYON_NUM_THREADS"]=json!("32");env["ZOPRO_CPU_GROUPING_LOWER_BOUND"]=json!(if mode=="on"{"1"}else{"0"});steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-31",binary,c["image"],c["request"],"1",d],"environment":env,"timeout_seconds":120}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",proofroot,"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));}}
 save(r.join("preflight-pins.json"),&json!(pins));save(r.join("preflight-plan.json"),&json!({"version":1,"source_pins":r.join("preflight-pins.json"),"environment":{},"steps":steps}));
 config["blocks"]=json!(3);config["cases"]=json!(cases);config["variants"]=variants;config["profile_cases"]=json!(["1x2-w32"]);config["profile_blocks"]=json!(1);config["frequency_hz"]=json!(199);config["checks"]=json!([]);config["pins"]=json!(pins);config["prior_proof_sha256"]=json!(prior);save(r.join("perf-template.json"),&config);println!("Frozen18preflights,81latencyprocesses,3profiles; prior5238");}
fn qualify(){let r=Path::new(ROOT);assert_eq!(read(r.join("preflight/result.json"))["status"],"complete");let mut c=read(r.join("perf-template.json"));let mut prior:BTreeSet<String>=serde_json::from_value(c["prior_proof_sha256"].clone()).unwrap();let mut inventory=BTreeMap::new();let mut pins:BTreeMap<String,String>=serde_json::from_value(c["pins"].clone()).unwrap();for case in c["cases"].as_array().unwrap(){for mode in ["off","on"]{let name=format!("{}-{mode}",case["name"].as_str().unwrap());let d=r.join("preflight-proofs").join(&name).join(Path::new(case["image"].as_str().unwrap()).file_stem().unwrap());assert_eq!(fs::metadata(d.join("0.proof")).unwrap().len(),164);assert_eq!(hash(d.join("0.public")),case["public_sha256"].as_str().unwrap());assert!(prior.insert(hash(d.join("0.proof"))));for part in ["0.proof","0.public"]{let p=d.join(part);inventory.insert(p.display().to_string(),hash(&p));add(p,&mut pins);}let v=fs::read_to_string(r.join("preflight").join(format!("verify-{name}/stdout.log"))).unwrap();assert!(v.lines().last().unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));let s=fs::read_to_string(r.join("preflight").join(format!("{name}/stdout.log"))).unwrap();let summary:Value=serde_json::from_str(s.lines().find_map(|s|s.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],1);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],32);}}
 assert_eq!(prior.len(),5256);save(r.join("preflight-proof-inventory.json"),&json!(inventory));save(r.join("preflight-analysis.json"),&json!({"status":"passed","sdk_requests":72,"distinct_gnark_exports":18,"prior_after":prior.len()}));for p in ["preflight-plan.json","preflight/result.json","preflight-analysis.json","preflight-proof-inventory.json"]{add(r.join(p),&mut pins);}c["pins"]=json!(pins);c["prior_proof_sha256"]=json!(prior);save(r.join("perf-plan.json"),&c);println!("Preflight72SDK18Gnark verified; prior5256");}
fn analyze(){let r=Path::new(ROOT);let c=read(r.join("perf-plan.json"));assert_eq!(read(r.join("performance/result.json"))["status"],"complete");for(p,h)in c["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let rows=read(r.join("performance/rows.json"));let rows=rows.as_array().unwrap();assert_eq!(rows.len(),84);let mut calibration=Vec::new();let mut regressions=Vec::new();let mut out=BTreeMap::new();let mut original_on_off=Vec::new();let mut original_on_accepted=Vec::new();let mut primary_ratio=0.;let mut primary_wins=0;
 for case in c["cases"].as_array().unwrap(){let name=case["name"].as_str().unwrap();let mut modes=BTreeMap::new();for variant in ["accepted","off","on"]{let rs:Vec<_>=rows.iter().filter(|x|x["case"]==name&&x["phase"]=="latency"&&x["variant"]==variant).collect();assert_eq!(rs.len(),3);modes.insert(variant,json!({"request_ms":median(rs.iter().map(|x|x["median_ms"].as_f64().unwrap()).collect()),"whole_process_maxrss_mib":rs.iter().map(|x|x["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0.,f64::max),"cpu_ms_per_request":median(rs.iter().map(|x|(x["summary"]["user_cpu_ms"].as_f64().unwrap()+x["summary"]["system_cpu_ms"].as_f64().unwrap())/31.).collect())}));}
  let mut off_acc=Vec::new();let mut on_off=Vec::new();let mut on_acc=Vec::new();for block in 0..3{let ms=|v:&str|rows.iter().find(|x|x["case"]==name&&x["phase"]=="latency"&&x["variant"]==v&&x["block"]==block).unwrap()["median_ms"].as_f64().unwrap();let a=ms("accepted");let off=ms("off");let on=ms("on");off_acc.push(off/a);on_off.push(on/off);on_acc.push(on/a);if !(1./1.05..=1.05).contains(&(off/a)){calibration.push(format!("{name} b{block} OFF/accepted={}",off/a));}}
  let paired=median(off_acc.clone());if !(1./1.03..=1.03).contains(&paired){calibration.push(format!("{name} paired OFF/accepted={paired}"));}let candidate=gm(&on_off);if name=="1x2-w32"{primary_ratio=candidate;primary_wins=on_off.iter().filter(|x|**x<1.).count();}else if candidate>1.02{regressions.push(format!("{name} ON/OFF={candidate}"));}if name!="merge-54x1-w32"{original_on_off.push(candidate);original_on_accepted.push(gm(&on_acc));}
  let m5=case["reference"].as_object().map(|reference|{let on=modes["on"]["request_ms"].as_f64().unwrap();json!({"supplied_cpu_ms":reference["cpu_ms"],"supplied_metal_ms":reference["metal_ms"],"candidate_CPU_speedup":reference["cpu_ms"].as_f64().unwrap()/on,"candidate_Metal_speedup":reference["metal_ms"].as_f64().unwrap()/on})});out.insert(name.to_owned(),json!({"latency":modes,"off_accepted_block_ratios":off_acc,"off_accepted_paired_median":paired,"on_off_block_ratios":on_off,"on_off_geomean":candidate,"on_accepted_geomean":gm(&on_acc),"M5":m5}));
 }
 let mut sdk=72;let mut profile_samples=0;let mut profiles=BTreeMap::new();for row in rows{let rounds=if row["phase"]=="latency"{31}else{51};assert_eq!(row["summary"]["rounds"],rounds);assert_eq!(row["summary"]["priming"],3);assert_eq!(row["summary"]["workers"],32);assert_eq!(row["samples_ms"].as_array().unwrap().len(),rounds);sdk+=rounds+3;if row["phase"]=="profile"{assert_eq!(row["case"],"1x2-w32");let p=&row["profile"];assert_eq!(p["lost_records"],0);assert_eq!(p["sampled_pids"].as_array().unwrap().len(),1);profile_samples+=p["samples"].as_u64().unwrap();profiles.insert(row["variant"].as_str().unwrap().to_owned(),p.clone());}}
 assert_eq!(sdk,2988);let mut inventory:BTreeMap<String,String>=serde_json::from_value(read(r.join("preflight-proof-inventory.json"))).unwrap();let perf=read(r.join("performance/proof-inventory.json"));assert_eq!(perf.as_object().unwrap().len(),168);for(p,h)in perf.as_object().unwrap(){let p=r.join("performance").join(p);assert_eq!(hash(&p),h.as_str().unwrap());assert!(inventory.insert(p.display().to_string(),h.as_str().unwrap().into()).is_none());}assert_eq!(inventory.len(),204);save(r.join("proof-inventory.json"),&json!(inventory));
 let original_ratio=gm(&original_on_off);let accepted_ratio=gm(&original_on_accepted);let adopt=calibration.is_empty()&&regressions.is_empty()&&primary_ratio<=0.98&&primary_wins>=2&&original_ratio<=0.995&&accepted_ratio<=0.995;
 save(r.join("analysis.json"),&json!({"sdk_requests":sdk,"distinct_gnark_exports":102,"proof_public_members":204,"profile_samples":profile_samples,"profiles":profiles,"calibration_failures":calibration,"regressions":regressions,"primary_on_off_geomean":primary_ratio,"primary_block_wins":primary_wins,"original_eight_on_off_geomean":original_ratio,"original_eight_on_accepted_geomean":accepted_ratio,"adoption_gate_passed":adopt,"adopted":false,"goal_achieved":false,"cases":out}));println!("Verified2988SDK102Gnark; primary ON/OFF{primary_ratio}, original8 {original_ratio}, adoptiongate{adopt}");}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("qualify")=>qualify(),Some("analyze")=>analyze(),_=>panic!("mode")}}
